sys_ui_action.script:
//Request Committee Review

if (current.mng_desc_injury == "")
    gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.mng_desc_injury"));

if (current.inc_req_prot_equip == "")
    gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.inc_req_prot_equip"));

if (current.emp_work_start == "")
    gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.emp_work_start"));

if (current.does_the_employee_now_require_modified_duties_as_a_result_of_this_injury == "")
    gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.does_the_employee_now_require_modified_duties_as_a_result_of_this_injury"));

if (current.inc_training_prov == "")
    gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.inc_training_prov"));

if (current.emp_age == "")
    gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.emp_age"));

if (current.emp_time_in_pos == "")
    gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.emp_time_in_pos"));

if (current.mng_inc_desc == "")
    gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.mng_inc_desc"));

if (current.inc_related_post_exp == "")
    gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.inc_related_post_exp"));

if (current.inc_related_illness == "")
    gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.inc_related_illness"));

if (current.implementation_date == "")
	gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.implementation_date"));

if (current.direct_causes_of_hazardous_occurrence == "")
    gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.direct_causes_of_hazardous_occurrence"));
if (current.direct_causes_of_hazardous_occurrence != ""){
	if (current.please_specify_cause_of_hazardous_occurrence == "")
		gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.please_specify_cause_of_hazardous_occurrence"));
}

if (current.training_spec == "")
    gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.training_spec"));

if (current.weather == "")
    gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.weather"));

if (current.emp_work_end == "")
    gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.emp_work_end"));

if (current.inc_type_occ == "")
    gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.inc_type_occ"));

if (current.did_the_employee_consult_a_healthcare_professional_as_a_result_of_this_injury == "")
    gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.did_the_employee_consult_a_healthcare_professional_as_a_result_of_this_injury"));

if (current.did_this_incident_result_in_an_injury == "")
    gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.did_this_incident_result_in_an_injury"));

if (current.was_the_employee_on_modified_duties_at_the_time_of_the_incident == "")
    gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.was_the_employee_on_modified_duties_at_the_time_of_the_incident"));

if (current.date_and_time_of_occurrence == "")
    gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.date_and_time_of_occurrence"));

if (current.correct_meas_imp_date == "")
    gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.correct_meas_imp_date"));

if (current.employee_gender == "")
    gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.employee_gender"));

if (current.dir_cause_injury == "")
    gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs. dir_cause_injury"));

current.update();
 action.setRedirectURL(current);



if (current.mng_desc_injury != '' && current.inc_req_prot_equip != '' && current.emp_work_start != '' && current.does_the_employee_now_require_modified_duties_as_a_result_of_this_injury != '' && current.implementation_date != "" &&
    current.inc_training_prov != '' && current.emp_age != '' &&
    current.emp_time_in_pos != '' && current.mng_inc_desc != '' && current.inc_related_post_exp != '' && current.inc_related_illness != '' && current.direct_causes_of_hazardous_occurrence != '' && current.please_specify_cause_of_hazardous_occurrence != '' && current.training_spec != '' && current.weather != '' && current.emp_work_end != '' && current.inc_type_occ != '' && current.did_the_employee_consult_a_healthcare_professional_as_a_result_of_this_injury != '' && current.did_this_incident_result_in_an_injury != '' && current.was_the_employee_on_modified_duties_at_the_time_of_the_incident != '' && current.date_and_time_of_occurrence != '' && current.correct_meas_imp_date != '' && current.employee_gender != '' && current.dir_cause_injury != '') {
    current.state = 30;
    current.update();
    action.setRedirectURL(current);

}
